import { useEffect, useState } from 'react'
import { View, Text, ActivityIndicator , TouchableOpacity } from 'react-native'
import { Image } from 'expo-image'
import { DeviceMotion } from 'expo-sensors'
import Animated, { useSharedValue, withSpring, useAnimatedStyle, useReducedMotion } from 'react-native-reanimated'
import { Svg, LinearGradient, Rect, Stop } from 'react-native-svg'
import { useCardDetail } from '../hooks/useCardDetail'
import { useUnlinkRequest } from '../hooks/useUnlinkRequest'
import { ConfirmModal } from '@/components/common/ConfirmModal'
import { secureStore } from '@/api/secureStore'
import { fonts, colors, rarityConfig } from '@/theme/index'

export function CardDetailModal({ templateId }: { templateId: number }) {
  const [userId, setUserId] = useState<number | null>(null)
  useEffect(() => {
    secureStore.get('userId').then(id => {
      if (id) setUserId(Number(id))
    })
  }, [])

  const { data: card, isLoading } = useCardDetail(templateId, userId)
  const unlinkRequest = useUnlinkRequest()
  const [showUnlinkConfirm, setShowUnlinkConfirm] = useState(false)
  const [showPendingState, setShowPendingState] = useState(false)
  const prefersReduced = useReducedMotion()

  const tiltX = useSharedValue(0)
  const tiltY = useSharedValue(0)

  useEffect(() => {
    if (prefersReduced) return
    const sub = DeviceMotion.addListener(({ rotation }) => {
      // Rotation in radians -> convert logic for tilt mapping
      tiltX.value = withSpring(rotation.beta * 10)  // front-back 
      tiltY.value = withSpring(rotation.gamma * 10) // left-right
    })
    DeviceMotion.setUpdateInterval(16)
    return () => {
      sub.remove()
    }
  }, [prefersReduced, tiltX, tiltY])

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [
      { perspective: 1000 },
      { rotateX: `${tiltX.value}deg` },
      { rotateY: `${tiltY.value}deg` },
    ],
  }))

  const shimmerStyle = useAnimatedStyle(() => {
    const magnitude = Math.min(Math.abs(tiltX.value) + Math.abs(tiltY.value), 20)
    return {
      opacity: (magnitude / 20) * 0.5,
    }
  })

  if (isLoading || !card) {
    return (
      <View className="flex-1 bg-[#0A0D1E] justify-center items-center">
        <ActivityIndicator size="large" color={colors.primary} />
      </View>
    )
  }

  const rarity = rarityConfig[card.cardTemplate.rarity]
  const isLegendary = card.cardTemplate.rarity === 'LEGENDARY'

  return (
    <View className="flex-1 bg-[#0A0D1E] items-center justify-center p-6">
      <Animated.View 
        style={[
          animatedStyle,
          {
            width: '100%',
            aspectRatio: 2.5/3.5,
            backgroundColor: 'rgba(26, 32, 64, 0.85)',
            borderColor: rarity.border,
            borderWidth: isLegendary ? 3 : 1,
            borderRadius: 20,
            overflow: 'hidden',
          },
          rarity.glow as any
        ]}
      >
        <Image 
          source={{ uri: card.cardTemplate.imageUrl }}
          className="w-full h-[60%]"
          contentFit="cover"
        />

        {/* Hologram Shimmer layer for Legendary */}
        {isLegendary && (
          <Animated.View style={[shimmerStyle]} className="absolute top-0 left-0 right-0 bottom-[40%]">
            <Svg height="100%" width="100%">
              <LinearGradient id="grad" x1="0" y1="0" x2="1" y2="1">
                <Stop offset="0" stopColor="#D4B857" stopOpacity="0.8" />
                <Stop offset="0.5" stopColor="#FFFFFF" stopOpacity="0.2" />
                <Stop offset="1" stopColor="#D4B857" stopOpacity="0.8" />
              </LinearGradient>
              <Rect width="100%" height="100%" fill="url(#grad)" />
            </Svg>
          </Animated.View>
        )}

        <View className="flex-1 p-4 bg-black/50">
          <Text style={{ fontFamily: fonts.heading, color: colors.primary }} className="text-2xl mb-1">
            {card.cardTemplate.name}
          </Text>
          <Text style={{ fontFamily: fonts.stats, color: rarity.color }} className="text-sm font-bold mb-3 uppercase tracking-wider">
            {rarity.label} ΓÇó {card.cardTemplate.collection.name}
          </Text>
          <Text style={{ fontFamily: fonts.body, color: colors.textMuted }} className="text-sm leading-5">
            {card.cardTemplate.description}
          </Text>

          {/* Pending state OR Unlink button */}
          {showPendingState ? (
            <View className="mt-4 p-3 rounded bg-[#1A1A24] border border-border">
              <Text style={{ fontFamily: fonts.bodyMedium, color: colors.textMuted }} className="text-center text-sm">
                ΓÅ│ Y├¬u cß║ºu hß╗ºy ─æang chß╗¥ ph├¬ duyß╗çt
              </Text>
            </View>
          ) : (
            card.nfcUid && (
              <TouchableOpacity
                onPress={() => setShowUnlinkConfirm(true)}
                className="mt-4 py-3 rounded-lg border border-border flex-row items-center justify-center bg-error/10"
              >
                <Text style={{ fontFamily: fonts.bodyMedium, color: colors.error }} className="text-base text-center">
                  Y├¬u cß║ºu hß╗ºy li├¬n kß║┐t
                </Text>
              </TouchableOpacity>
            )
          )}
        </View>
      </Animated.View>

      <ConfirmModal
        visible={showUnlinkConfirm}
        title="Hß╗ºy li├¬n kß║┐t thß║╗"
        body="Y├¬u cß║ºu hß╗ºy li├¬n kß║┐t sß║╜ cß║ºn Staff ph├¬ duyß╗çt. Bß║ín c├│ chß║»c muß╗æn tiß║┐p tß╗Ñc?"
        confirmLabel="Gß╗¡i y├¬u cß║ºu"
        onConfirm={() => {
          if (card.nfcUid) {
            unlinkRequest.mutate(card.nfcUid, {
              onSuccess: () => {
                setShowUnlinkConfirm(false)
                setShowPendingState(true)
              },
              onError: () => {
                // 409 handled in hook with Toast
                setShowUnlinkConfirm(false)
              }
            })
          }
        }}
        onCancel={() => setShowUnlinkConfirm(false)}
        loading={unlinkRequest.isPending}
      />
    </View>
  )
}

import { fonts, rarityConfig } from '@/theme/index'
import type { UserInventory } from '@/types/inventory'
import type { MarketCardTemplate } from '@/types'
import { Image } from 'expo-image'
import { useEffect } from 'react'
import { Pressable, Text, View } from 'react-native'
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withRepeat,
  withSequence,
  withTiming,
} from 'react-native-reanimated'

interface Props {
  card?: UserInventory
  template?: MarketCardTemplate
  onPress: () => void
}

export function CardThumbnail({ card, template, onPress }: Props) {
  const itemTemplate = template ?? card?.cardTemplate
  const isLegendary = itemTemplate?.rarity === 'LEGENDARY'

  const pulseAnim = useSharedValue(1)

  useEffect(() => {
    if (isLegendary) {
      pulseAnim.value = withRepeat(
        withSequence(
          withTiming(1.3, { duration: 1500 }),
          withTiming(1, { duration: 1500 })
        ),
        -1, // infinite
        true // reverse
      )
    }
  }, [isLegendary, pulseAnim])

  const animatedGlowStyle = useAnimatedStyle(() => {
    if (!itemTemplate) return {}
    const rarity = rarityConfig[itemTemplate.rarity]
    if (!isLegendary || !rarity.glow) return {}
    return {
      shadowOpacity: rarity.glow.shadowOpacity * pulseAnim.value,
      shadowRadius: rarity.glow.shadowRadius * pulseAnim.value,
    }
  })

  if (!itemTemplate) return null
  const rarity = rarityConfig[itemTemplate.rarity]

  return (
    <Pressable onPress={onPress} className="w-1/2 p-2">
      <Animated.View
        style={[
          {
            borderColor: rarity.border,
            borderWidth: isLegendary ? 2 : 1,
            backgroundColor: 'rgba(26, 32, 64, 0.85)',
          },
          rarity.glow && !isLegendary ? (rarity.glow as any) : {},
          animatedGlowStyle,
        ]}
        className="rounded-xl overflow-hidden aspect-[2.5/3.5] bg-[#0d1126]"
      >
        <Image
          source={{ uri: itemTemplate.imageUrl }}
          className="flex-1 w-full"
          contentFit="cover"
          transition={200}
        />
        <View className="absolute bottom-0 left-0 right-0 p-2 bg-black/70">
          <Text
            style={{ fontFamily: fonts.heading }}
            className="text-white text-sm"
            numberOfLines={1}
          >
            {itemTemplate.name}
          </Text>
          <Text
            style={{ fontFamily: fonts.stats, color: rarity.color }}
            className="text-xs mt-1"
          >
            {rarity.label}
          </Text>
        </View>
      </Animated.View>
    </Pressable>
  )
}

import * as Linking from 'expo-linking'
import { useEffect } from 'react'
import { useRouter } from 'expo-router'
import { secureStore } from '@/api/secureStore'

export function useAndroidNfcDeepLink() {
  const router = useRouter()

  useEffect(() => {
    Linking.getInitialURL().then((url) => {
      if (url) handleNfcUrl(url, router)
    })

    const sub = Linking.addEventListener('url', ({ url }) => {
      handleNfcUrl(url, router)
    })

    return () => sub.remove()
  }, [])
}

function handleNfcUrl(url: string, router: ReturnType<typeof useRouter>) {
  const parsed = Linking.parse(url)
  const pathParts = (parsed.path ?? '').split('/').filter(Boolean)

  if (pathParts[0] === 'nfc' && pathParts[1]) {
    const uid = pathParts[1]
    secureStore.get('accessToken').then((token) => {
      if (!token) {
        router.replace({ pathname: '/(auth)/login', params: { returnUid: uid } })
      } else {
        router.push({ pathname: '/(modals)/nfc-scan', params: { uid } })
      }
    })
  }
}
